def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_prev.append(float(bid))

    if not alive_opps:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.25)))

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    urgent_prev = max(dangerous_prev) if dangerous_prev else high_prev

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    if hp <= 2 or no_water >= 2:
        bid = max(urgent_prev + 2.0, DAILY_SALARY * 0.95)
        return float(min(budget, bid))

    if hp <= 4 or no_water >= 1:
        target = max(avg_prev + 3.0, DAILY_SALARY * (0.72 - 0.10 * scarcity))
        target = min(target, DAILY_SALARY * 1.15)
        return float(min(budget, target))

    if high_prev >= 150:
        bid = DAILY_SALARY * (0.18 + 0.10 * scarcity)
    elif high_prev >= 110:
        bid = DAILY_SALARY * (0.28 + 0.12 * scarcity)
    elif high_prev > 0:
        bid = max(DAILY_SALARY * 0.42, avg_prev + 2.5)
    else:
        bid = DAILY_SALARY * 0.45

    if day >= 8 and hp >= 6:
        bid *= 0.9

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.55)

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, take what we can afford
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Read yesterday's immediate pressure from previous_trace
    prev_bids = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base bid depends on supply: higher supply means we can underbid
    # Approximate number of water units available
    units = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0

    # Determine a target bid level
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If someone was bidding extremely high yesterday, we slightly overtake but not too much.
        # Otherwise, bid just above the second-highest to steal the marginal unit.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # My hp is good; avoid panic overpaying.
            if my_hp > 6:
                target = min(my_budget, DAILY_SALARY * 0.32)
            else:
                target = min(my_budget, DAILY_SALARY * 0.75)
        else:
            # Use relative position: aim above second-highest.
            # Add a small increment scaled down when supply is higher.
            increment = 2.0 + 6.0 * max(0.0, (2.0 - units) / 2.0)
            target = second_prev_bid + increment
            # Keep target within reasonable bounds
            lower = DAILY_SALARY * 0.35
            upper = DAILY_SALARY * 0.65
            target = max(lower, min(upper, target))
            target = min(my_budget, target)
    else:
        # No trace info: conservative moderate bid
        if my_hp > 6:
            target = min(my_budget, DAILY_SALARY * 0.42)
        else:
            target = min(my_budget, DAILY_SALARY * 0.85)

    # Ensure we bid at least enough to matter, but never exceed budget
    if my_budget <= 0:
        return 0.0

    # If supply is high, reduce bid; if low, increase slightly
    if supply >= 21.0:
        target *= 0.9
    elif supply <= 17.0:
        target *= 1.08

    # Final clamp
    target = float(max(0.0, min(my_budget, target)))
    return target

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace')]
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80.0

    # If supply is high, bid conservatively. If low, match or exceed the average.
    if supply >= 20:
        bid = avg_prev_bid * 0.7
    elif supply <= 16:
        bid = avg_prev_bid * 1.1
    else:
        bid = avg_prev_bid * 0.9

    # Emergency survival check
    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 1.2)

    return float(min(my_status['budget'], bid))
